//! Issue #559: candidate retry loops follow C's draw / cap / occupancy order.
//!
//! The fixture is generated by `c_toolbox/hopping_retry_559/generate.sh` from the
//! verbatim C candidate functions (see its README). Each case feeds the same raw
//! words through the `SamplingRng` seam and checks the candidate, the words the
//! candidate consumed, and the conditional Metropolis word that the sampling
//! engines draw only for a non-rejected candidate.

use mvmc_core::sampling::candidate::{
    make_candidate_hopping, make_candidate_hopping_fsz, make_candidate_local_spin_flip_conduction,
};
use mvmc_core::sampling::rng::SamplingRng;

const FIXTURE: &str = include_str!("../../../tests/fixtures/candidate/hopping_retry_cap_559.txt");

/// Supplied raw-word tape; running past its end is a draw-count defect.
struct TapeRng {
    words: Vec<u32>,
    cursor: usize,
}

impl SamplingRng for TapeRng {
    fn gen_rand32(&mut self) -> u32 {
        let word = *self
            .words
            .get(self.cursor)
            .unwrap_or_else(|| panic!("tape exhausted after {} words", self.cursor));
        self.cursor += 1;
        word
    }
    fn words_consumed(&self) -> u128 {
        self.cursor as u128
    }
    fn dump_rand32(&self, out: &mut [u32]) {
        for (slot, word) in out.iter_mut().zip(self.words[self.cursor..].iter()) {
            *slot = *word;
        }
    }
}

#[derive(Debug, Default)]
struct Case {
    name: String,
    kind: String,
    nsite: usize,
    nelec: usize,
    loc_spn: Vec<i64>,
    ele_idx: Vec<i64>,
    ele_cfg: Vec<i64>,
    ele_spn: Vec<i64>,
    words: Vec<u32>,
    /// `mi ri rj s t reject candidate_words words_after_metropolis`.
    result: Vec<i64>,
}

fn parse<T: std::str::FromStr>(rest: &str) -> Vec<T>
where
    T::Err: std::fmt::Debug,
{
    rest.split_ascii_whitespace()
        .map(|v| v.parse().unwrap())
        .collect()
}

fn cases() -> Vec<Case> {
    let mut out = Vec::new();
    let mut case = Case::default();
    for line in FIXTURE.lines() {
        let (key, rest) = line.split_once(' ').unwrap_or((line, ""));
        match key {
            "case" => {
                let (name, kind) = rest.split_once(' ').unwrap();
                case = Case {
                    name: name.to_owned(),
                    kind: kind.to_owned(),
                    ..Case::default()
                };
            }
            "nsite" => case.nsite = rest.trim().parse().unwrap(),
            "nelec" => case.nelec = rest.trim().parse().unwrap(),
            "loc_spn" => case.loc_spn = parse(rest),
            "ele_idx" => case.ele_idx = parse(rest),
            "ele_cfg" => case.ele_cfg = parse(rest),
            "ele_spn" => case.ele_spn = parse(rest),
            "words" => case.words = parse(rest),
            "result" => case.result = parse(rest),
            "end" => out.push(std::mem::take(&mut case)),
            other => panic!("unexpected fixture key {other:?}"),
        }
    }
    out
}

#[test]
fn candidate_retry_loops_match_c_fixture() {
    let cases = cases();
    assert_eq!(cases.len(), 13);
    for c in &cases {
        let mut words = c.words.clone();
        words.push(0x7fff_ffff); // Metropolis marker, as in the C probe.
        let mut rng = TapeRng { words, cursor: 0 };
        let (mi, ri, rj, s, t, reject) = match c.kind.as_str() {
            "hopping" => {
                let h = make_candidate_hopping(
                    &c.ele_idx, &c.ele_cfg, c.nsite, c.nelec, &c.loc_spn, &mut rng,
                );
                (h.mi, h.ri, h.rj, h.spin, h.spin, h.reject)
            }
            "hopping_fsz" | "hopping_csz" => {
                let two_sz = if c.kind == "hopping_fsz" { -1 } else { 0 };
                let h = make_candidate_hopping_fsz(
                    &c.ele_idx, &c.ele_cfg, &c.ele_spn, &c.loc_spn, c.nsite, c.nelec, two_sz,
                    &mut rng,
                );
                (h.mi, h.ri, h.rj, h.spin, h.spin_to, h.reject)
            }
            "conduction" => {
                let h = make_candidate_local_spin_flip_conduction(
                    &c.ele_idx, &c.ele_cfg, &c.ele_spn, &c.loc_spn, c.nsite, c.nelec, &mut rng,
                );
                (h.mi, h.ri, h.rj, h.spin, h.spin_to, h.reject)
            }
            other => panic!("unknown kind {other}"),
        };
        let candidate_words = rng.words_consumed() as i64;
        if !reject {
            let _ = rng.genrand_real2();
        }
        let got = vec![
            mi as i64,
            ri as i64,
            rj as i64,
            i64::from(s),
            i64::from(t),
            i64::from(reject),
            candidate_words,
            rng.words_consumed() as i64,
        ];
        assert_eq!(got, c.result, "case {}", c.name);
    }
}

/// With no itinerant electron, C's source loop never terminates (unsupported
/// input). Rust rejects after the Julia guard's `Nsite^2 + 1` electron draws.
#[test]
fn hopping_without_itinerant_electron_rejects_after_guard() {
    let n_site = 2;
    let loc_spn = [1, 1];
    let ele_idx = [0, 1];
    let ele_cfg = [0, -1, -1, 0];
    let mut rng = TapeRng {
        words: vec![0; 2 * (n_site * n_site + 1)],
        cursor: 0,
    };
    let c = make_candidate_hopping(&ele_idx, &ele_cfg, n_site, 1, &loc_spn, &mut rng);
    assert!(c.reject);
    assert_eq!(rng.words_consumed(), 2 * (n_site * n_site + 1) as u128);
}
